1|// Pure upload routing: which path a parsed book takes. Client-safe.
2|export const FREE_BOOK_MAX_WORDS = 50_000; // provisional, may change once we know the processing cost
3|export const WORDS_PER_PAGE = 250;
4|
5|export function approxPages(words: number): number {
6|  return Math.max(1, Math.round(words / WORDS_PER_PAGE));
7|}
8|
9|export type UploadRoute = { kind: "free" } | { kind: "byok"; reason: "too_long" | "free_used" };
10|
11|// A long book needs its own key even when the free book is still unused.
12|export function uploadRoute(words: number, freeBookUsed: boolean): UploadRoute {
13|  if (words > FREE_BOOK_MAX_WORDS) return { kind: "byok", reason: "too_long" };
14|  if (freeBookUsed) return { kind: "byok", reason: "free_used" };
15|  return { kind: "free" };
16|}

