1|// Preloaded classics for the home library grid. Ready favorites first,
2|// the rest in manifest order, so new books need no UI change.
3|import manifest from "../data/library.json";
4|
5|export interface LibraryBook {
6|  id: string;
7|  title: string;
8|  author: string;
9|  year: number;
10|  words: number;
11|  gutenbergId: number;
12|  status: "ready";
13|  favorite?: boolean;
14|}
15|
16|function isBook(value: unknown): value is LibraryBook {
17|  if (typeof value !== "object" || value === null) return false;
18|  const b = value as Record<string, unknown>;
19|  return (
20|    typeof b.id === "string" &&
21|    typeof b.title === "string" &&
22|    typeof b.author === "string" &&
23|    typeof b.year === "number" &&
24|    typeof b.words === "number" &&
25|    typeof b.gutenbergId === "number" &&
26|    b.status === "ready" &&
27|    (b.favorite === undefined || typeof b.favorite === "boolean")
28|  );
29|}
30|
31|export function loadLibrary(raw: unknown = manifest): LibraryBook[] {
32|  if (!Array.isArray(raw)) throw new Error("library manifest must be an array");
33|  const books = raw.map((entry) => {
34|    if (!isBook(entry)) throw new Error(`bad library entry: ${JSON.stringify(entry)}`);
35|    return entry;
36|  });
37|  return [...books].sort((a, b) => Number(b.favorite ?? false) - Number(a.favorite ?? false));
38|}
39|
40|// 250 words/min, rounded to the minute.
41|export function readingMinutes(words: number): string {
42|  const total = Math.max(1, Math.round(words / 250));
43|  const hours = Math.floor(total / 60);
44|  const mins = total % 60;
45|  if (hours === 0) return `About ${mins} min`;
46|  if (mins === 0) return `About ${hours} h`;
47|  return `About ${hours} h ${mins} min`;
48|}
49|
50|export const library: LibraryBook[] = loadLibrary();

