83|    <item id="cover" href="cover.png" media-type="image/png"/>
84|  </manifest>
85|  <spine toc="ncx"><itemref idref="ch1"/></spine>
86|</package>`;
87|  const ncx = `<?xml version="1.0" encoding="utf-8"?>
88|<ncx xmlns="http://www.daisy.org/z3986/2005/ncx/" version="2005-1"><navMap>
89|<navPoint id="a"><navLabel><text>First</text></navLabel><content src="ch1.xhtml"/></navPoint>
90|<navPoint id="b"><navLabel><text>Second</text></navLabel><content src="ch1.xhtml"/></navPoint>
91|</navMap></ncx>`;
92|  return epub3(opf, {
93|    "OEBPS/toc.ncx": strToU8(ncx),
94|    "OEBPS/ch1.xhtml": strToU8(chapterDoc("hello world")),
95|    "OEBPS/cover.png": PNG_1X1,
96|  });
97|}
98|
99|function codeOf(fn: () => unknown): string {
100|  try {
101|    fn();
102|  } catch (err) {
103|    if (err instanceof EpubError) return err.code;
104|    throw err;
105|  }
106|  throw new Error("expected an EpubError");
107|}
108|
109|describe("parseEpub", () => {
110|  it("parses an EPUB 3: title, author, chapters, words, cover", () => {
111|    const book = parseEpub(tinyEpub3());
112|    expect(book.title).toBe("The Wonderful Wizard of Oz");
113|    expect(book.author).toBe("L. Frank Baum");
114|    expect(book.chapters).toEqual([
115|      "Chapter I. The Cyclone",
116|      "Chapter II. The Council with the Munchkins",
117|      "Chapter III. How Dorothy Saved the Scarecrow",
118|    ]);
119|    expect(book.words).toBe(6);
120|    expect(book.cover?.mediaType).toBe("image/png");
121|    expect(book.cover?.bytes.length).toBeGreaterThan(0);
122|  });
123|
124|  it("parses an EPUB 2 with NCX and meta cover", () => {
125|    const book = parseEpub(tinyEpub2());
126|    expect(book.title).toBe("Oz Two");
127|    expect(book.author).toBe("Baum");
128|    expect(book.chapters).toEqual(["First", "Second"]);
129|    expect(book.words).toBe(2);
130|    expect(book.cover?.mediaType).toBe("image/png");
131|  });
132|
133|  it("rejects non-EPUBs", () => {
134|    expect(codeOf(() => parseEpub(new Uint8Array([1, 2, 3, 4])))).toBe("not_epub");
135|    expect(codeOf(() => parseEpub(zipSync({ "META-INF/container.xml": strToU8(CONTAINER) })))).toBe("not_epub");
136|    const tampered = zipSync({
137|      mimetype: strToU8("text/plain"),
138|      "META-INF/container.xml": strToU8(CONTAINER),
139|      "OEBPS/content.opf": strToU8(OPF3),
140|      "OEBPS/nav.xhtml": strToU8(NAV),
141|    });
142|    expect(codeOf(() => parseEpub(tampered))).toBe("not_epub");
143|  });
144|
145|  it("refuses copy-protected books but allows font obfuscation", () => {
146|    const rights = epub3(OPF3, {
147|      "META-INF/rights.xml": strToU8("<rights/>"),
148|      "OEBPS/nav.xhtml": strToU8(NAV),
149|      "OEBPS/ch1.xhtml": strToU8(chapterDoc("x")),
150|    });
151|    expect(codeOf(() => parseEpub(rights))).toBe("drm");
152|    const aes =
153|      `<encryption xmlns="http://www.w3.org/2001/04/xmlenc#"><EncryptedData>` +
154|      `<EncryptionMethod Algorithm="http://www.w3.org/2001/04/xmlenc#aes128-cbc"/></EncryptedData></encryption>`;
155|    const fonts =
156|      `<encryption xmlns="http://www.w3.org/2001/04/xmlenc#"><EncryptedData>` +
157|      `<EncryptionMethod Algorithm="http://www.idpf.org/2008/embedding"/></EncryptedData></encryption>`;
158|    const enc = (xml: string) =>
159|      epub3(OPF3, {
160|        "META-INF/encryption.xml": strToU8(xml),
161|        "OEBPS/nav.xhtml": strToU8(NAV),
162|        "OEBPS/ch1.xhtml": strToU8(chapterDoc("x")),
163|      });
164|    expect(codeOf(() => parseEpub(enc(aes)))).toBe("drm");
165|    expect(parseEpub(enc(fonts)).chapters).toHaveLength(3);
166|  });
167|
168|  it("counts long books fully instead of rejecting them", () => {
169|    const big = epub3(OPF3, {
170|      "OEBPS/nav.xhtml": strToU8(NAV),
171|      "OEBPS/ch1.xhtml": strToU8(chapterDoc(`${"word ".repeat(60_000)}`)),
172|      "OEBPS/ch2.xhtml": strToU8(chapterDoc("x")),
173|      "OEBPS/ch3.xhtml": strToU8(chapterDoc("x")),
174|    });
175|    expect(parseEpub(big).words).toBe(60_002);
176|  });
177|
178|  it("reports broken files as unreadable", () => {
179|    const broken = epub3("this is not < xml", {
180|      "OEBPS/nav.xhtml": strToU8(NAV),
181|      "OEBPS/ch1.xhtml": strToU8(chapterDoc("x")),
182|    });
183|    expect(codeOf(() => parseEpub(broken))).toBe("unreadable");
184|    expect(() => assertEntrySize(8 * 1024 * 1024 + 1)).toThrow(EpubError);
185|    expect(() => assertEntrySize(100)).not.toThrow();
186|  });
187|
188|  it("has warm copy for every code", () => {
189|    for (const code of ["not_epub", "too_large", "drm", "unreadable"] as const) {
190|      expect(EPUB_ERROR_MESSAGES[code].length).toBeGreaterThan(20);
191|    }
192|  });
193|});
