197|    let read = false;
198|    const fake = {
199|      size: MAX_EPUB_BYTES + 1,
200|      arrayBuffer: async () => {
201|        read = true;
202|        return new ArrayBuffer(0);
203|      },
204|    } as unknown as File;
205|    await expect(readEpubFile(fake)).rejects.toMatchObject({ code: "too_large" });
206|    expect(read).toBe(false);
